declare(strict_types=1);require $argv[1].'/HostWebControl.php';$c=json_decode(file_get_contents($argv[2]),true,32,JSON_THROW_ON_ERROR);if(parse_url($c['origin'],PHP_URL_HOST)!=='127.0.0.1')exit(8);$o=(new ReflectionClass(HostWebControl::class))->newInstanceWithoutConstructor();foreach(['origin','private','key','token','config'] as $k)(new ReflectionProperty($o,$k))->setValue($o,$c[$k]);
